cat > rewrite-api.js <<'EOF'
function handler(event) {
  var request = event.request;
  if (request.uri.startsWith('/api/')) {
    request.headers['x-forwarded-prefix'] = { value: '/api' };
  }
  return request;
}
EOF

aws cloudfront create-function \
  --name strip-api-prefix \
  --function-config Comment='Tag API requests',Runtime=cloudfront-js-2.0 \
  --function-code fileb://rewrite-api.js
